def triples_sum_to_zero(numbers):
    numbers.sort()  # Sort the list to make it easier to find triplets

    for index in range(len(numbers)):
        left_index = index + 1
        right_index = len(numbers) - 1

        while left_index < right_index:
            current_sum = numbers[index] + numbers[left_index] + numbers[right_index]

            if current_sum == 0:
                return True
            elif current_sum > 0:
                right_index -= 1
            else:
                left_index += 1

