from typing import List, Tuple
def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """
    This function takes a list of integers as input and returns a tuple containing the sum and the product of all the integers in the list.
    If the list is empty, both the sum and the product will be zero and one respectively.
    """

    if not numbers:
        return (0, 1)

    total_sum = 0
    total_product = 1

    for num in numbers:
        total_sum += num
        total_product *= num


    return (total_sum, total_product)

